/**
 * Digest and wire-format parity with the Rust SDK.
 *
 * `digest_vectors.json` is generated by `cargo run --example digest_vectors`
 * in `packages/sdk-rust` — the payloads as the Rust SDK serializes them, with
 * the digests and recipient commitments it computes. A drift here means a
 * TypeScript-signed payment stops verifying where a Rust-signed one does, so
 * these are exact-match tests.
 */

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { clearingHouseDomain, recipientCommitment } from "@/guarantee";
import { CheckpointPayload, PaymentRequestPayload } from "@/models";

const VECTORS = JSON.parse(
  readFileSync(
    new URL("./fixtures/digest_vectors.json", import.meta.url),
    "utf8",
  ),
);
const DOMAIN = clearingHouseDomain(
  VECTORS.domain.chain_id,
  VECTORS.domain.verifying_contract,
);

describe("digest vectors", () => {
  it.each([
    "plain",
    "validated",
  ])("reproduces the %s payment digest", (name) => {
    const vector = VECTORS[name];
    const payload = PaymentRequestPayload.fromRpc(vector.payload);

    expect(payload.signingDigest(DOMAIN)).toBe(vector.eip712_digest);
    expect(
      recipientCommitment(
        payload.recipientAddress,
        payload.salt,
        payload.validation,
      ),
    ).toBe(vector.recipient_commitment);
  });

  it.each([
    "plain",
    "validated",
  ])("serializes the %s payment exactly as Rust does", (name) => {
    // Core reads what the Rust SDK writes, so the TypeScript wire form must
    // be the same JSON, field for field.
    const payload = VECTORS[name].payload;
    expect(PaymentRequestPayload.fromRpc(payload).toPayload()).toEqual(payload);
  });

  it("reproduces the checkpoint digest", () => {
    const vector = VECTORS.checkpoint;
    expect(
      CheckpointPayload.fromRpc(vector.payload).signingDigest(DOMAIN),
    ).toBe(vector.eip712_digest);
  });

  it("serializes the checkpoint exactly as Rust does", () => {
    const payload = VECTORS.checkpoint.payload;
    expect(CheckpointPayload.fromRpc(payload).toPayload()).toEqual(payload);
  });
});
